def solve():
    # Read input from stdin
    line = sys.stdin.read().strip()
    if not line:
        return

    # The problem provides a string s
    # If the input is wrapped in quotes or formatted as s = "...", clean it
    s = line
    if s.startswith('s = "') and s.endswith('"'):
        s = s[5:-1]
    elif s.startswith('"') and s.endswith('"'):
        s = s[1:-1]

    # Frequency map for all characters
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # The number of operations is the maximum frequency of any character
    max_freq = 0
    for char in counts:
        if counts[char] > max_freq:
            max_freq = counts[char]

    # We need to find characters that appear at least max_freq times.
    # Specifically, we want the last occurrence of characters that appear max_freq times,
    # and for any character that appears more than max_freq times (not possible here),
    # we'd take the occurrence at index (max_freq).
    # Actually, the simplest way: iterate backwards and pick the max_freq-th occurrence.

    result = []
