    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    # N is the number of beans
    n = int(input_data[0])

    # Dictionary to store the minimum deliciousness for each color
    # key: color, value: minimum deliciousness found so far for that color
    color_min_deliciousness = {}

    # Iterate through the input pairs of (deliciousness, color)
    # The input data starts from index 1 and each bean has 2 attributes
    for i in range(n):
        a = int(input_data[1 + 2*i])
        c = int(input_data[2 + 2*i])

        if c in color_min_deliciousness:
            # If color exists, update the minimum deliciousness
            if a < color_min_deliciousness[c]:
                color_min_deliciousness[c] = a
        else:
            # If color is new, initialize it
            color_min_deliciousness[c] = a

    # We want to maximize the minimum deliciousness among all chosen colors
    # The possible choices are the minimum deliciousness values for each color
    max_min_val = -1
    for min_val in color_min_deliciousness.values():
        if min_val > max_min_val:
            max_min_val = min_val

    print(max_min_val)

