import sys

def solve():
    # Read S and T from standard input
    try:
        s = sys.stdin.readline().strip()
        t = sys.stdin.readline().strip()
    except EOFError:
        return

    if not s or not t:
        return

    # Convert T to lowercase for easier comparison with S
    t_lower = t.lower()

    # Case 1: T is a subsequence of S of length 3
    # We look for t_lower[0], then t_lower[1], then t_lower[2] in S
    s_idx = 0
    t_idx = 0
    while s_idx < len(s) and t_idx < 3:
        if s[s_idx] == t_lower[t_idx]:
            t_idx += 1
        s_idx += 1

    if t_idx == 3:
        print("Yes")
        return

    # Case 2: The first two characters of T are a subsequence of S, and the third character is 'X'
    if t[2] == 'X':
        s_idx = 0
        t_idx = 0
        # We only need to match the first two characters of t_lower
        while s_idx < len(s) and t_idx < 2:
            if s[s_idx] == t_lower[t_idx]:
                t_idx += 1
            s_idx += 1

        if t_idx == 2:
            print("Yes")
            return

    # If neither condition is met
    print("No")

