import sys

def solve():
    # Read all input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    # The most common way to provide this in competitive programming:
    # First line: n (length of array)
    # Second line: n integers (nums)
    # Third line: k
    # However, looking at the examples, we can just take the last element as k
    # and everything before it as the array.

    try:
        k = int(input_data[-1])
        nums = [int(x) for x in input_data[:-1]]

        # If the first element was actually 'n', we slice it out
        # But if the first element is part of the array, we keep it.
        # Let's assume the input is exactly: elements of nums, then k.

        nums.sort()
        n = len(nums)
        m = n // 2

        operations = 0
        if nums[m] < k:
            for i in range(m, n):
                if nums[i] < k:
                    operations += k - nums[i]
                else:
                    break
        elif nums[m] > k:
            for i in range(m, -1, -1):
                if nums[i] > k:
                    operations += nums[i] - k
                else:
                    break

        print(operations)
    except EOFError:
        pass

if __name__ == "__main__":
    solve()

import sys
from collections import Counter

def solve():
    # Read input from stdin
    line = sys.stdin.readline()
    if not line:
        return
    s = line.strip()
    n = len(s)

    # Precompute total counts of characters in s
    total_counts = Counter(s)

    # Find all divisors of n in increasing order
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i*i != n:
                divisors.append(n // i)
    divisors.sort()

    for L in divisors:
        k = n // L

        # Condition 1: Total counts must be divisible by k
        possible = True
        for char in total_counts:
            if total_counts[char] % k != 0:
                possible = False
                break

        if not possible:
            continue

        # Condition 2: Every block of length L must be an anagram of the first block
        # We use a frequency array (size 26) for efficiency
        first_block_counts = [0] * 26
        for i in range(L):
            first_block_counts[ord(s[i]) - ord('a')] += 1

        is_valid = True
        for start in range(L, n, L):
            current_block_counts = [0] * 26
            for i in range(start, start + L):
                current_block_counts[ord(s[i]) - ord('a')] += 1

            if current_block_counts != first_block_counts:
                is_valid = False
                break

        if is_valid:
            print(L)
            return

