import sys

def solve():
    # Read input from stdin
    line = sys.stdin.read().strip()
    if not line:
        return

    # The input might be provided as s = "string", we need to extract the string
    if '=' in line:
        s = line.split('=')[1].strip().strip('"').strip("'")
    else:
        s = line.strip().strip('"').strip("'")

    n = len(s)
    # dp[i] will store the minimum number of balanced substrings for s[0...i-1]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        # We check all possible substrings ending at i: s[j...i-1]
        # To optimize, we can maintain character counts as we decrease j
        counts = {}
        distinct_chars = 0

        # Iterate backwards from i-1 to 0 to check substrings s[j:i]
        for j in range(i - 1, -1, -1):
            char = s[j]
            if char not in counts:
                counts[char] = 0
                distinct_chars += 1
            counts[char] += 1

            # A substring is balanced if all present characters have the same frequency.
            # The frequency must be (length of substring) / (number of distinct characters).
            length = i - j
            if length % distinct_chars == 0:
                freq = length // distinct_chars
                is_balanced = True
                # We check if all values in the counts dictionary are equal to freq
                # Since we only have at most 26 keys, this is fast.
                for val in counts.values():
                    if val != freq:
                        is_balanced = False
                        break

                if is_balanced:
                    if dp[j] + 1 < dp[i]:
                        dp[i] = dp[j] + 1

    print(dp[n])

if __name__ == "__main__":
