import sys

def solve():
    # Read N, M, K from the first line
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        n, m, k = map(int, line1)
    except ValueError:
        return

    tests = []
    for _ in range(m):
        parts = sys.stdin.readline().split()
        if not parts:
            break

        # parts[0] is C_i (number of keys)
        # parts[1...C_i] are the keys A_{i,j}
        # parts[C_i + 1] is the result R_i
        c_i = int(parts[0])
        keys = [int(x) for x in parts[1:c_i+1]]
        result = parts[c_i+1]

        # Convert keys to a bitmask (0-indexed)
        mask = 0
        for key in keys:
            mask |= (1 << (key - 1))

        tests.append((mask, result))

    count = 0
    # Iterate through all 2^N possible combinations of real/dummy keys
    # A bit set to 1 means the key is real, 0 means it is a dummy.
    for i in range(1 << n):
        possible = True
        for mask, result in tests:
            # Count how many real keys are in the current test set
            # i & mask gives the bits that are set in both the combination and the test set
            real_keys_count = bin(i & mask).count('1')

            if result == 'o':
                # Door opens if at least K real keys are inserted
                if real_keys_count < k:
                    possible = False
                    break
            else: # result == 'x'
                # Door does not open if fewer than K real keys are inserted
                if real_keys_count >= k:
                    possible = False
                    break

        if possible:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read N from standard input
    line = sys.stdin.readline()
    if not line:
        return
    n = int(line.strip())

    # A level-0 carpet is a single black cell
    carpet = [['#']]

    # Iteratively build level-K carpet from level-(K-1) carpet
    for k in range(1, n + 1):
        prev_size = 3**(k-1)
        current_size = 3**k
        # Initialize current carpet with white cells
        new_carpet = [['.' for _ in range(current_size)] for _ in range(current_size)]

        # Fill the 8 surrounding blocks with the previous level's carpet
        for r_block in range(3):
            for c_block in range(3):
                # The central block (1, 1) remains white
                if r_block == 1 and c_block == 1:
                    continue

                # Copy the prev_size x prev_size carpet into the block
                start_r = r_block * prev_size
                start_c = c_block * prev_size
                for r in range(prev_size):
                    for c in range(prev_size):
                        new_carpet[start_r + r][start_c + c] = carpet[r][c]

        carpet = new_carpet

    # Print the final carpet
    for row in carpet:
        print("".join(row))

if __name__ == "__main__":
    solve()

import sys
from itertools import combinations

def solve():
    # Read N and M from the first line of input
    try:
        line = sys.stdin.readline().split()
        if not line:
            return
        n, m = map(int, line)
    except ValueError:
        return

    # Read the strings and convert them to bitmasks
    # Bitmask representation: j-th bit is 1 if stand i sells flavor j
    stands_masks = []
    for _ in range(n):
        s = sys.stdin.readline().strip()
        mask = 0
        for j in range(m):
            if s[j] == 'o':
                mask |= (1 << j)
        stands_masks.append(mask)

    # Target mask: all M flavors are present (M bits set to 1)
    target_mask = (1 << m) - 1

    # We want to find the minimum number of stands k (from 1 to N)
    # such that there exists a combination of k stands whose union of masks equals target_mask.
    for k in range(1, n + 1):
        # Iterate through all combinations of k stands
        for combo in combinations(stands_masks, k):
            current_mask = 0
            for mask in combo:
                current_mask |= mask

            if current_mask == target_mask:
                print(k)
                return

