    max_c = -1

    # Iterate through the grid to find the boundaries of all 1s
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    # Calculate height and width of the bounding box
    height = max_r - min_r + 1
    width = max_c - min_c + 1

    # Print the area
    print(height * width)

if __name__ == "__main__":
    solve()

