def solve():
    # Read n from standard input
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except EOFError:
        return
    except ValueError:
        return

    result = []

    def generate(current_string):
        # Base case: if the string reaches length n, add to result
        if len(current_string) == n:
            result.append(current_string)
            return

        # We can always append '1'
        generate(current_string + '1')

        # We can append '0' only if the last character was not '0'
        if not current_string or current_string[-1] == '1':
            generate(current_string + '0')

    generate("")

    # The problem asks for the list of strings. 
    # Since the output format in the example is a list, we print it as such.
    # Using json.dumps or simply printing the list.
    print(result)

