    if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
        s = s[1:-1]

    # Dictionary to count frequencies of each character
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1

    min_length = 0
    for count in char_counts.values():
        # If count is odd, it reduces to 1
        # If count is even, it reduces to 2
        if count % 2 == 1:
            min_length += 1
        else:
