import sys

def solve():
    # Read all input and normalize it to a list of integers
    input_text = sys.stdin.read()
    # Replace characters that aren't digits or whitespace with spaces
    normalized = ""
    for char in input_text:
        if char.isdigit() or char.isspace():
            normalized += char
        else:
            normalized += " "

    tokens = normalized.split()
    if not tokens:
        return

    # Standard competitive programming format: m n then the matrix
    m = int(tokens[0])
    n = int(tokens[1])

    # The remaining tokens are the elements of the matrix
    flat_grid = tokens[2:]

    # Calculate row flips
    row_flips = 0
    for i in range(m):
        for j in range(n // 2):
            # Index in flat_grid: row_index * n + col_index
            val1 = flat_grid[i * n + j]
            val2 = flat_grid[i * n + (n - 1 - j)]
            if val1 != val2:
                row_flips += 1

    # Calculate col flips
    col_flips = 0
    for j in range(n):
        for i in range(m // 2):
            # Index in flat_grid: row_index * n + col_index
            val1 = flat_grid[i * n + j]
            val2 = flat_grid[(m - 1 - i) * n + j]
            if val1 != val2:
                col_flips += 1

    print(min(row_flips, col_flips))

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read N and K from the first line of input
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        n = int(line1[0])
        k = int(line1[1])

        # Read R_i values from the second line of input
        line2 = sys.stdin.readline().split()
        if not line2:
            # Handle cases where R_i might be on separate lines
            r = []
            while len(r) < n:
                more = sys.stdin.readline().split()
                if not more:
                    break
                r.extend(map(int, more))
        else:
            r = list(map(int, line2))
    except EOFError:
        return

    # We need to find all sequences (A_1, ..., A_N) such that:
    # 1 <= A_i <= R_i
    # sum(A_i) % K == 0
    # Sequences should be printed in lexicographical order.

    current_sequence = [0] * n

    def backtrack(index, current_sum):
        # Base case: if we have filled all positions
        if index == n:
            if current_sum % k == 0:
                print(*(current_sequence))
            return

        # Try values for the current position in increasing order to maintain lexicographical order
        for val in range(1, r[index] + 1):
            current_sequence[index] = val
            backtrack(index + 1, current_sum + val)

    # Start the recursion from the first element
    backtrack(0, 0)

