import sys

def solve():
    # Read the input string
    s = sys.stdin.readline().strip()
    if not s:
        return

    # Dictionary to store positions of each character
    positions = {}
    for idx, char in enumerate(s):
        if char not in positions:
            positions[char] = []
        positions[char].append(idx + 1) # Using 1-based indexing as per problem

    total_triples = 0

    # For each character, calculate the sum of (p_b - p_a - 1)
    for char in positions:
        p = positions[char]
        m = len(p)
        if m < 2:
            continue

        prefix_sum = 0
        for b in range(m):
            # b is the 0-indexed counter, so there are 'b' elements before p[b]
            # The formula: b * p[b] - sum(p[0...b-1]) - b
            total_triples += b * p[b] - prefix_sum - b
            prefix_sum += p[b]

    print(total_triples)

