import sys

def solve():
    # Read H, W, D
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        h, w, d = map(int, line1)
    except ValueError:
        return

    grid = []
    for _ in range(h):
        grid.append(sys.stdin.readline().strip())

    # Identify all floor cells
    floors = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == '.':
                floors.append((r, c))

    num_floors = len(floors)

    # Precompute which floor cells are covered by a humidifier placed at floor[i]
    # coverage[i] is a bitmask where the j-th bit is 1 if floor[j] is within distance D of floor[i]
    coverage = [0] * num_floors
    for i in range(num_floors):
        r1, c1 = floors[i]
        mask = 0
        for j in range(num_floors):
            r2, c2 = floors[j]
            if abs(r1 - r2) + abs(c1 - c2) <= d:
                mask |= (1 << j)
        coverage[i] = mask

    max_humidified = 0

    # Try all pairs of distinct floor cells to place humidifiers
    for i in range(num_floors):
        mask_i = coverage[i]
        for j in range(i + 1, num_floors):
            mask_j = coverage[j]

            # The total humidified floor cells is the number of set bits in the union of masks
            combined_mask = mask_i | mask_j

            # Count set bits (bin(n).count('1') is efficient enough for small masks)
            count = bin(combined_mask).count('1')

            if count > max_humidified:
                max_humidified = count

    print(max_humidified)

