    solve()

import sys
import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def get_score(arr):
    if not arr:
        return 0

    current_gcd = arr[0]
    current_lcm = arr[0]

    for i in range(1, len(arr)):
        current_gcd = gcd(current_gcd, arr[i])
        current_lcm = lcm(current_lcm, arr[i])

    return current_gcd * current_lcm

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    # The input is expected to be a list of integers. 
    # Since the problem format in the prompt is a class method, 
    # we adapt it to read from stdin.
    # Assuming input is provided as a space-separated list of integers.
    try:
        nums = [int(x) for x in input_data]
    except ValueError:
        return

    # Option 1: Remove no elements
    max_score = get_score(nums)

    # Option 2: Remove one element at index i
    for i in range(len(nums)):
        # Create a new list without the element at index i
        subset = nums[:i] + nums[i+1:]
        max_score = max(max_score, get_score(subset))

    print(max_score)

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    # The problem description implies we are given an array. 
    # Since the starter code was a class method, but the requirement is a script,
    # we assume the input is a sequence of integers.
    # However, standard competitive programming inputs often start with n.
    # Given the constraints and examples, we treat all input as the array nums.
    try:
        nums = [int(x) for x in input_data]
    except ValueError:
        return

    n = len(nums)
    total_sum = sum(nums)

    # Create a frequency map for O(1) lookup of the sum element
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1

    # Sort nums in descending order to find the largest outlier first
    sorted_nums = sorted(nums, reverse=True)

    for outlier in sorted_nums:
        # Target sum element nums[j] must satisfy: 2 * nums[j] = total_sum - outlier
        target_2j = total_sum - outlier

        if target_2j % 2 == 0:
            target_j = target_2j // 2
            if target_j in counts:
                # We must ensure the outlier and sum element are at distinct indices.
                # If outlier == target_j, we need at least 2 occurrences of that value.
                if outlier != target_j or counts[outlier] >= 2:
                    print(outlier)
                    return

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read the input string S
    try:
        s = sys.stdin.read().strip()
    except EOFError:
        return

    if not s:
        # Depending on interpretation, an empty string is usually a valid bracket sequence.
        # However, constraints say length is between 1 and 2*10^5.
        print("Yes")
        return

    # Use a stack to simulate the deletion of contiguous matching pairs.
    # This is the standard algorithm for checking balanced bracket sequences.
    stack = []

    # Map of closing brackets to their corresponding opening brackets.
    mapping = {')': '(', ']': '[', '>': '<'}

    for char in s:
        if char in mapping:
            # If the current character is a closing bracket, check if the stack
            # is not empty and the top of the stack is the matching opening bracket.
            if stack and stack[-1] == mapping[char]:
                stack.pop()
            else:
                # If it doesn't match or stack is empty, it's not a colorful bracket sequence.
                print("No")
                return
        else:
            # If it's an opening bracket, push it onto the stack.
            stack.append(char)

    # After processing the entire string, the stack must be empty for it to be a colorful sequence.
    if not stack:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

