import sys

def solve():
    # Read N from the first line of input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = input_data[1:]

    # last_pos stores the last index where each number was encountered
    last_pos = {}
    min_length = float('inf')

    for i in range(n):
        val = a[i]
        if val in last_pos:
            # Calculate length of subarray from previous occurrence to current
            length = i - last_pos[val] + 1
            if length < min_length:
                min_length = length

        # Update the last seen position of the current value
        last_pos[val] = i

    if min_length == float('inf'):
        print("-1")
    else:
        print(min_length)

if __name__ == "__main__":
    solve()

import sys
from collections import Counter

def solve():
    # Read input from standard input
    try:
        line = sys.stdin.read()
        if not line:
            return
        cards = list(map(int, line.split()))
    except EOFError:
        return

    # Count the frequency of each card value
    counts = Counter(cards)

    # Get the list of values that appear in the cards
    distinct_values = list(counts.keys())

    # A full house requires two distinct values x and y
    # such that x appears at least 3 times and y appears at least 2 times.
    possible = False
    for x in distinct_values:
        for y in distinct_values:
            if x == y:
                continue

            if counts[x] >= 3 and counts[y] >= 2:
                possible = True
                break
        if possible:
            break

    if possible:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read N from the first line of input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = list(map(int, input_data[1:]))

    # Count the occurrences of each integer
    counts = {}
    for x in a:
        counts[x] = counts.get(x, 0) + 1

    max_val = -1
    ans_label = -1

    # Iterate through the people to find those with unique values
    for i in range(n):
        val = a[i]
        if counts[val] == 1:
            # We want the person with the greatest integer
            if val > max_val:
                max_val = val
                ans_label = i + 1

    # Print the result
    print(ans_label)

