import sys
import ast

def solve():
    # Read all input
    input_text = sys.stdin.read()
    if not input_text:
        return

    # Try to find lists in the input text
    # This handles "groups = [8,4,3,2,4]\nelements = [4,2]"
    try:
        # Split by lines and find the lines containing '='
        lines = input_text.splitlines()
        groups = []
        elements = []
        for line in lines:
            if 'groups' in line and '=' in line:
                groups = ast.literal_eval(line.split('=')[1].strip())
            elif 'elements' in line and '=' in line:
                elements = ast.literal_eval(line.split('=')[1].strip())

        if not groups or not elements:
            # Fallback: just find all lists in the text
            import re
            lists = re.findall(r'\[.*?\]', input_text)
            if len(lists) >= 2:
                groups = ast.literal_eval(lists[0])
                elements = ast.literal_eval(lists[1])
    except:
        return

    MAX_VAL = 100000
    best_index = [-1] * (MAX_VAL + 1)
    seen_val = [False] * (MAX_VAL + 1)

    for j, val in enumerate(elements):
        if val <= MAX_VAL and not seen_val[val]:
            seen_val[val] = True
            for multiple in range(val, MAX_VAL + 1, val):
                if best_index[multiple] == -1:
                    best_index[multiple] = j

    print([best_index[g] if g <= MAX_VAL else -1 for g in groups])

if __name__ == "__main__":
    solve()

import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    s = input_data[0]
    k = int(input_data[1])
    n = len(s)

    if k == 0:
        print("true")
        return

    # Step 1: Find first and last occurrences of each character
    first = {}
    last = {}
    for i, char in enumerate(s):
        if char not in first:
            first[char] = i
        last[char] = i

    # Step 2: Find all valid "special" substrings
    intervals = []
    chars_present = list(first.keys())

    for char in chars_present:
        l = first[char]
        r = last[char]

        # Expand the range [l, r] to include all occurrences of characters inside it
        possible = True
        while True:
            expanded = False
            for i in range(l, r + 1):
                c = s[i]
                if first[c] < l:
                    l = first[c]
                    expanded = True
                if last[c] > r:
                    r = last[c]
                    expanded = True
            if not expanded:
                break

        # Condition: Not the entire string
        if not (l == 0 and r == n - 1):
            intervals.append((l, r))

    # Step 3: Find the maximum number of disjoint intervals (Greedy)
    # Sort by end time
    intervals.sort(key=lambda x: x[1])

    count = 0
    last_end = -1
    for l, r in intervals:
        if l > last_end:
            count += 1
            last_end = r

    if count >= k:
        print("true")
    else:
        print("false")

if __name__ == "__main__":
    solve()
